<span class="line"><span style="color:#E06C75;">    needs</span><span style="color:#ABB2BF;">: [</span><span style="color:#98C379;">test</span><span style="color:#ABB2BF;">, </span><span style="color:#98C379;">security-scan</span><span style="color:#ABB2BF;">]</span></span>
